71	class WorksViewportRuntime {
72	  private readonly _pixelRatioMax: number;
73	
74	  constructor(pixelRatioMax: number) {
75	    this._pixelRatioMax = pixelRatioMax;
76	  }
77	
78	  read(): WorksViewportSnapshot {
79	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
80	    return {
81	      width: snapshot.viewportWidth,
82	      height: snapshot.viewportHeight,
83	      dpr: Math.min(snapshot.render.clampedPixelRatio, this._pixelRatioMax),
84	    };
85	  }
86	
87	  readHalfView(camera: THREE.Camera): WorksHalfViewBounds {
88	    if (camera instanceof THREE.OrthographicCamera) {
89	      return {
90	        hW: (camera.right - camera.left) * 0.5,
91	        hH: (camera.top - camera.bottom) * 0.5,
92	      };
93	    }
94	    const perspectiveCamera = camera as THREE.PerspectiveCamera;
95	    const fov = (perspectiveCamera.fov * Math.PI) / 180;
96	    const halfHeight = Math.tan(fov / 2) * perspectiveCamera.position.z;
97	    return {
98	      hW: halfHeight * perspectiveCamera.aspect,
99	      hH: halfHeight,
100	    };
101	  }
102	}
