104	class WorksHitRuntime {
105	  private readonly _raycaster = new THREE.Raycaster();
106	  private readonly _mouse2d = new THREE.Vector2();
107	
108	  resolve(
109	    camera: THREE.Camera,
110	    viewport: WorksViewportSnapshot,
111	    pointer: WorksPointerSample,
112	    meshes: THREE.Mesh[],
113	  ): THREE.Mesh | null {
114	    this._mouse2d.set(
115	      (pointer.x / viewport.width) * 2 - 1,
116	      -(pointer.y / viewport.height) * 2 + 1,
117	    );
118	    this._raycaster.setFromCamera(this._mouse2d, camera);
119	    const hit = this._raycaster.intersectObjects(meshes, false)[0];
120	    return (hit?.object as THREE.Mesh | undefined) ?? null;
121	  }
122	}
