124	class WorksCameraMotionRuntime {
125	  private readonly _layout: WorkLayoutConstants;
126	  private readonly _camPadX: number;
127	  private readonly _camPadY: number;
128	  private _baseCamZ: number;
129	  private _isDragging = false;
130	  private _dragPrevious: WorksPointerSample = { x: 0, y: 0 };
131	  private _targetX = 0;
132	  private _targetY = 0;
133	  private _velocityX = 0;
134	  private _velocityY = 0;
135	  private _targetZ: number;
136	
137	  constructor(
138	    layout: WorkLayoutConstants,
139	    camPadX: number,
140	    camPadY: number,
141	    camZ: number,
142	  ) {
143	    this._layout = layout;
144	    this._camPadX = camPadX;
145	    this._camPadY = camPadY;
146	    this._baseCamZ = camZ;
147	    this._targetZ = camZ;
148	  }
149	
150	  activateScatter(): void {
151	    this._targetZ = this._baseCamZ;
152	  }
153	
154	  setTargetPosition(targetX: number, targetY: number): void {
155	    this._targetX = targetX;
156	    this._targetY = targetY;
157	  }
158	
159	  setTargetZ(targetZ: number): void {
160	    this._targetZ = targetZ;
161	  }
162	
163	  readBaseCamZ(): number {
164	    return this._baseCamZ;
165	  }
166	
167	  setBaseCamZ(baseCamZ: number): void {
168	    this._baseCamZ = baseCamZ;
169	    this._targetZ = baseCamZ;
170	  }
171	
172	  primeFromCamera(camera: THREE.PerspectiveCamera): void {
173	    this._targetX = camera.position.x;
174	    this._targetY = camera.position.y;
175	    this._targetZ = camera.position.z;
176	  }
177	
178	  primeFromCameraPosition(targetX: number, targetY: number, targetZ: number): void {
179	    this._targetX = targetX;
180	    this._targetY = targetY;
181	    this._targetZ = targetZ;
182	  }
183	
184	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
185	    this._isDragging = true;
186	    this._dragPrevious = { ...pointer };
187	    this._velocityX = 0;
188	    this._velocityY = 0;
189	    this._targetX = camera.position.x;
190	    this._targetY = camera.position.y;
191	  }
192	
193	  endDrag(): void {
194	    this._isDragging = false;
195	  }
196	
197	  updateDrag(
198	    viewport: WorksViewportSnapshot,
199	    halfView: WorksHalfViewBounds,
200	    pointer: WorksPointerSample,
201	  ): void {
202	    if (!this._isDragging) return;
203	    const dx = pointer.x - this._dragPrevious.x;
204	    const dy = pointer.y - this._dragPrevious.y;
205	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
206	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
207	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7;
208	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7;
209	    this._targetX = Math.max(
210	      -this._camPadX + halfView.hW,
211	      Math.min(this._camPadX - halfView.hW, this._targetX),
212	    );
213	    this._targetY = Math.max(
214	      -this._camPadY + halfView.hH,
215	      Math.min(this._camPadY - halfView.hH, this._targetY),
216	    );
217	    this._dragPrevious = { ...pointer };
218	  }
219	
220	  updateFrame(camera: THREE.Camera, delta: number): void {
221	    if (this._isDragging) {
222	      const decay = Math.pow(this._layout.velDecay, delta * 60);
223	      this._velocityX *= decay;
224	      this._velocityY *= decay;
225	      this._targetX += this._velocityX * delta * 60;
226	      this._targetY += this._velocityY * delta * 60;
227	    }
228	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
229	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
230	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
231	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
232	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
233	    camera.lookAt(camera.position.x, camera.position.y, 0);
234	  }
235	
236	  get isDragging(): boolean {
237	    return this._isDragging;
238	  }
239	}
