241	class WorksMeshRuntime {
242	  create(
243	    scene: THREE.Scene,
244	    projects: ReadonlyArray<WorkProjectItem>,
245	    positions: ReadonlyArray<WorksScatterPosition>,
246	    config: WorkCanvasConfig,
247	  ): WorksSceneCardMeshResources {
248	    const cardSize: WorkCardSize = {
249	      w: config.cardWidth,
250	      h: config.cardHeight,
251	    };
252	    const meshes: THREE.Mesh[] = [];
253	    positions.forEach((position, placed) => {
254	      const project = projects[placed % projects.length];
255	      const detailPath = project?.detailPath ?? "/works";
256	      const mesh = WorkCard.createMesh(
257	        project,
258	        cardSize,
259	        detailPath,
260	        SCATTER_CARD_RENDER_OPTIONS,
261	      );
262	      mesh.position.set(position.x, position.y, 0);
263	      scene.add(mesh);
264	      meshes.push(mesh);
265	    });
266	    return {
267	      meshes,
268	      cardSize,
269	    };
270	  }
271	
272	  dispose(meshes: ReadonlyArray<THREE.Mesh>): void {
273	    meshes.forEach((mesh) => {
274	      const material = mesh.material as THREE.MeshBasicMaterial;
275	      material.map?.dispose();
276	      material.dispose();
277	      mesh.geometry.dispose();
278	    });
279	  }
280	}
