282	class WorksThumbnailRuntime {
283	  async warm(
284	    meshes: ReadonlyArray<THREE.Mesh>,
285	    placeholderImage: string,
286	    cardSize: WorkCardSize,
287	    log: (step: string, payload?: Record<string, unknown>) => void,
288	  ): Promise<void> {
289	    let fallback: HTMLImageElement | null = null;
290	    const ensureFallback = async (): Promise<HTMLImageElement> => {
291	      if (!fallback) {
292	        fallback = await WorkCard.loadPlaceholderImage(placeholderImage);
293	      }
294	      return fallback;
295	    };
296	
297	    let index = 0;
298	    const batchSize = 4;
299	    const runBatch = async (): Promise<void> => {
300	      const end = Math.min(index + batchSize, meshes.length);
301	      const slice = meshes.slice(index, end);
302	      await Promise.all(
303	        slice.map(async (mesh) => {
304	          if (!mesh) return;
305	          const userData = mesh.userData as WorkCardUserData;
306	          const material = mesh.material as THREE.MeshBasicMaterial;
307	          const map = material.map;
308	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
309	          const thumb = userData.proj.thumbnailImage?.trim() ?? "";
310	          let img: HTMLImageElement;
311	          if (thumb) {
312	            try {
313	              img = await WorkCard.loadImage(thumb);
314	            } catch {
315	              img = await ensureFallback();
316	            }
317	          } else {
318	            img = await ensureFallback();
319	          }
320	          WorkCard.updateTextureImage(
321	            map,
322	            userData.proj,
323	            cardSize,
324	            img,
325	            SCATTER_CARD_RENDER_OPTIONS,
326	          );
327	        }),
328	      );
329	      index = end;
330	      log("warmThumbnails.batch", { updatedUntil: index, total: meshes.length });
331	      if (index < meshes.length) {
332	        FrameScheduler.request(() => {
333	          void runBatch();
334	        });
335	      }
336	    };
337	    void runBatch();
338	  }
339	}
