353	  private readonly viewportRuntime: WorksViewportRuntime;
354	  private readonly hitRuntime = new WorksHitRuntime();
355	  private readonly meshRuntime = new WorksMeshRuntime();
356	  private readonly thumbnailRuntime = new WorksThumbnailRuntime();
357	  private readonly cameraMotionRuntime: WorksCameraMotionRuntime;
358	  private readonly onSelect?: (detailPath: string) => void;
359	  private readonly onInteractionStart?: () => void;
360	  private canvas: HTMLCanvasElement | null = null;
361	  private scene: THREE.Scene | null = null;
362	  private camera: THREE.Camera | null = null;
363	  private renderer: THREE.WebGLRenderer | null = null;
364	  private meshes: THREE.Mesh[] = [];
