366	  private cleanup: Array<() => void> = [];
367	  private viewMode: WorksViewMode = "scatter";
368	  private clock: THREE.Clock | null = null;
369	  private activePointerId: number | null = null;
370	  private hovered: THREE.Mesh | null = null;
371	  private mouseDownX = 0;
372	  private mouseDownY = 0;
373	  private mouseDownMesh: THREE.Mesh | null = null;
374	  private dragInteractionStarted = false;
375	  private readonly camPadX: number;
376	  private readonly camPadY: number;
377	  private readonly scatterPositions: WorksScatterPosition[];
378	  private readonly categoryScatterPositions: WorksScatterPosition[];
379	  private targetPositions: WorksScatterPosition[] = [];
380	  private interactiveMeshes: THREE.Mesh[] = [];
381	  private activeCategory: string | null;
382	  /** 직전 `applyCategory` 호출 직전의 필터 (전환 이징용) */
383	  private _filterPrevCategory: string | null = null;
384	  private _filterBlendStartMs = 0;
385	
386	  constructor(options: WorksSceneManagerOptions) {
387	    this.root = options.root;
388	    this.config = options.config;
389	    this.layout = options.layout;
390	    this.projects = options.projects;
391	    this.canvasId = options.canvasId;
392	    this.rendererConfig = options.renderer;
393	    this.placeholderImage = options.placeholderImage;
394	    this.introEntryState = options.introEntryState ?? null;
395	    this.onSelect = options.onSelect;
396	    this.onInteractionStart = options.onInteractionStart;
397	    this.activeCategory = options.initialCategory ?? null;
398	    this.camPadX = options.config.spreadX * 0.5 + 5;
399	    this.camPadY = options.config.spreadY * 0.5 + 5;
400	    this.viewportRuntime = new WorksViewportRuntime(options.pixelRatioMax);
401	    this.cameraMotionRuntime = new WorksCameraMotionRuntime(
402	      options.layout,
403	      this.camPadX,
404	      this.camPadY,
405	      options.config.camZ,
406	    );
407	    this.scatterPositions = buildScatterPositions(
408	      options.config.totalCards,
409	      options.config.spreadX,
410	      options.config.spreadY * 0.88,
411	    );
412	    this.categoryScatterPositions = sortScatterPositionsFromCenter(this.scatterPositions);
413	    this.targetPositions = [...this.scatterPositions];
414	  }
415	
416	  init(): void {
417	    if (this.projects.length === 0) return;
418	    this.start();
419	  }
420	
421	  setViewMode(mode: WorksViewMode): void {
422	    if (this.viewMode === mode) return;
423	    this.viewMode = mode;
424	    if (mode === "grid") {
425	      this.hovered = null;
426	      this.mouseDownMesh = null;
427	      this.dragInteractionStarted = false;
428	      this.activePointerId = null;
429	      this.cameraMotionRuntime.endDrag();
430	      this.stopLoop();
