506	  update(delta: number): void {
507	    if (!this.camera || !this.scene) return;
508	    const camera = this.camera;
509	    this.cameraMotionRuntime.updateFrame(camera, delta);
510	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
511	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
512	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
513	    const isGridView = this.viewMode === "grid";
514	    const hover =
515	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
516	    const blendT =
517	      this._filterBlendStartMs > 0
518	        ? Math.min(
519	            1,
520	            (performance.now() - this._filterBlendStartMs) /
521	              WorksSceneManager._filterBlendMs,
522	          )
523	        : 1;
524	    const filterEase = 1 - Math.pow(1 - blendT, 3);
525	    for (let index = 0; index < this.meshes.length; index += 1) {
526	      const mesh = this.meshes[index];
527	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
528	      const isActiveCategory = this.isMeshInCategory(mesh);
529	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
530	      const nowIn = isActiveCategory;
531	      let targetY = target.y;
532	      if (wasIn && !nowIn && blendT < 1) {
533	        targetY += (1 - filterEase) * 6.5;
534	      }
535	      if (!wasIn && nowIn && blendT < 1) {
536	        targetY -= (1 - filterEase) * 7.5;
537	      }
538	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
539	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
540	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
541	      mesh.quaternion.copy(camera.quaternion);
542	      const opacityAnchor = isActiveCategory ? target : mesh.position;
543	      const distance = dist2d(
544	        camera.position.x,
545	        camera.position.y,
546	        opacityAnchor.x,
547	        opacityAnchor.y,
548	      );
549	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
550	      if (!isActiveCategory) targetOpacity = 0;
551	      if (isActiveCategory && this.activeCategory !== null) {
552	        targetOpacity = Math.max(0.3, targetOpacity);
553	      }
554	      if (isGridView) targetOpacity = 0;
555	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
556	      if (nowIn && !wasIn) {
557	        targetOpacity *= filterEase;
558	      }
559	      const material = mesh.material as THREE.MeshBasicMaterial;
560	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
561	      const steadyScale = hover === mesh ? 1.06 : 1;
562	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
563	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
564	    }
565	  }
