713	    };
714	    const onResize = (): void => {
715	      if (!this.camera || !this.renderer) return;
716	      const viewport = this.viewportRuntime.read();
717	      if (this.camera instanceof THREE.OrthographicCamera) {
718	        const halfHeight =
719	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
720	        const halfWidth = halfHeight * (viewport.width / viewport.height);
721	        this.camera.left = -halfWidth;
722	        this.camera.right = halfWidth;
723	        this.camera.top = halfHeight;
724	        this.camera.bottom = -halfHeight;
