148	
149	    this._objectSetup = new ObjectSetup();
150	    const config = WorksSceneDefinition.createIntroPageConfig(canvasId, initialState);
151	    await this._objectSetup.init(engine, config);
152	    if (this._disposed || this._engine !== engine) return null;
153	
154	    engine.setState(initialState);
155	    engine.start(() => undefined, () => undefined);
156	
157	    for (const step of introConfig.steps) {
158	      if (this._disposed || this._engine !== engine) return null;
159	      await this._playStep(step);
160	    }
161	
162	    const lastStep = introConfig.steps[introConfig.steps.length - 1] ?? null;
163	    return readWorksTheatreStepState(lastStep, 1);
