600	
601	  private _createMedia(
602	    item: WorkApiItem,
603	  ): HTMLVideoElement | HTMLImageElement | null {
604	    if (item.thumbnailImage) {
605	      const image = document.createElement("img");
606	      image.src = item.thumbnailImage;
607	      image.alt = item.title ?? "";
608	      return image;
609	    }
610	    if (item.thumbnailVideo) {
611	      const video = document.createElement("video");
612	      video.src = item.thumbnailVideo;
613	      video.autoplay = true;
614	      video.muted = true;
615	      video.loop = true;
616	      video.playsInline = true;
617	      return video;
618	    }
619	    return null;
