622	  private _createModalButton(item: WorkApiItem): HTMLButtonElement {
623	    const button = document.createElement("button");
624	    button.type = "button";
625	    button.className =
626	      "no-corner-btn no-works-canvas__grid-link js-work-modal-trigger";
627	    button.setAttribute("aria-label", `${item.title || "Work"} modal view`);
628	    button.append(this._createModalButtonCorner());
629	    const text = document.createElement("span");
630	    text.className = "no-corner-btn__text";
