767	    overlay.style.position = "fixed";
768	    overlay.style.inset = "0";
769	    overlay.style.zIndex = "99999";
770	    overlay.style.pointerEvents = "auto";
771	    overlay.style.touchAction = "none";
772	    overlay.style.background = "transparent";
773	    overlay.style.cursor = "wait";
774	    document.body.appendChild(overlay);
775	    this._overlay = overlay;
776	  }
