933	  private async startScatter(runRevision: number): Promise<void> {
934	    const hasWebgl = EnvSetup.checkWebGL();
935	    const hasCanvasHost = EnvSetup.checkCanvas(
936	      WORK_CANVAS_CONFIG.canvasId,
937	      this.root,
938	    );
939	    const canRun = hasWebgl && hasCanvasHost;
940	    if (!canRun) {
941	      this._fallbackToGridView();
942	      return;
943	    }
944	
945	    const projectsPromise = this.projectsLoader.load(this.state);
946	    const introStatePromise = this._playScatterIntro(runRevision);
947	    let projects: WorkProjectItem[];
948	    try {
949	      projects = await projectsPromise;
950	    } catch (error) {
951	      if (!this._isActiveRun(runRevision)) return;
952	      if (this.projectsLoader.isAbortedError(error)) return;
953	      throw error;
954	    }
955	    if (!this._isActiveRun(runRevision)) return;
956	    const introState = await introStatePromise;
957	    if (!this._isActiveRun(runRevision)) return;
958	
959	    if (projects.length === 0) {
960	      this._fallbackToGridView();
961	      return;
962	    }
963	
964	    this.scene?.dispose();
965	    this.scene = new WorksSceneManager({
966	      root: this.root,
967	      config: WORK_CANVAS_CONFIG,
968	      layout: WORK_LAYOUT,
969	      projects,
970	      introEntryState: introState
971	        ? {
972	            camera: introState.camera,
973	            cameraTarget: introState.cameraTarget,
974	          }
975	        : null,
976	      initialCategory: this.state.category,
977	      onSelect: (detailPath) => this.navigateToDetail(detailPath),
978	      onInteractionStart: () => this.uiRuntime?.hideDragHint(),
979	      canvasId: WORK_CANVAS_CONFIG.canvasId,
980	      pixelRatioMax: WORK_PIXEL_RATIO_MAX,
981	      renderer: WORK_RENDERER_CONFIG,
982	      placeholderImage: WORK_PLACEHOLDER_IMAGE,
983	    });
984	    this.scene.init();
985	    this.scene.setViewMode("scatter");
986	    this.scene.showCanvas();
987	    this._hidePanel();
988	    this.scene.applyInitialScatterState();
989	    if (!this._isActiveRun(runRevision)) return;
990	
991	    this.uiRuntime?.syncFilterSelection(this.state.category);
992	    this._bindScatterFilter(this.scene);
993	
994	    this.uiRuntime?.hideIntroIfReady();
995	    this.uiRuntime?.hideGrid();
996	    this._bindWheelHint();
997	    this.uiRuntime?.showViewToggle();
998	    if (WORK_HINT_CONFIG.enabled) {
999	      this.uiRuntime?.showDragHintIfNeeded(this.state);
1000	    }
1001	  }
