265	  private constructor() {
266	    this._config = readWorksTheatreConfigSource();
267	    this._stateSource = readWorksTheatreStateSource();
268	    this._project = TheatreProjectSession.open<Record<string, unknown>, Record<string, unknown>>(
269	      WORKS_THEATRE_PROJECT_ID,
