309	  readState(sheetId: WorksTheatreSheetId, progress: number): WorksTheatreValue {
310	    const range = this.readCameraPlaybackRange(sheetId);
311	    const position =
312	      range.start + (range.end - range.start) * Helpers.clamp01(progress);
313	    const state = this._readSheetState(sheetId, position);
314	    return {
315	      camera: {
316	        position: { ...state.camera.position },
317	        fov: state.camera.fov,
318	      },
319	      cameraTarget: {
320	        position: { ...state.camera.target },
321	      },
322	      sceneLights: {
323	        ...state.sceneLights,
324	        ground: {
325	          position: { ...state.sceneLights.ground.position },
326	          rotation: { ...state.sceneLights.ground.rotation },
327	          scale: { ...state.sceneLights.ground.scale },
328	          visible: state.sceneLights.ground.visible,
329	        },
330	      },
331	      window: {
332	        ...state.window,
333	      },
334	    };
335	  }
