213	  async run(
214	    canvasId: string,
215	    canvasElement?: HTMLCanvasElement | null,
216	  ): Promise<void> {
217	    const engine = createWorksEngine(canvasId, canvasElement);
218	    if (!engine.init()) return;
219	    this._engine = engine;
220	    this._objectSetup = new ObjectSetup();
221	    const config = WorksSceneDefinition.createIntroPageConfig(
222	      canvasId,
223	      WorksSceneDefinition.createInitialState(
224	        createWorksAuthorSceneState(createDefaultWorksAuthorState()),
225	      ),
226	    );
227	    await this._objectSetup.init(engine, config);
228	    engine.setState(config.initialState ?? {});
229	    engine.start(() => undefined, () => undefined);
230	
231	    const renderer = engine.getRenderer() as { domElement?: HTMLCanvasElement } | null;
232	    const domElement = renderer?.domElement;
233	    if (!domElement) return;
234	    this._controls = new OrbitControls(engine.getCamera(), domElement);
235	    this._controls.target = engine.getCameraTarget().position;
236	    this._controls.enableDamping = true;
237	    this._controls.update();
