245	        state: readWorksTheatreAuthorStateSource() ?? undefined,
246	      },
247	    );
248	    await project.ready;
249	    WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
250	      const sheet = TheatreSheetSession.open(project, sheetId);
251	      const object = sheet.object(
252	        WORKS_THEATRE_OBJECT_ID,
253	        createWorksAuthorState(engine),
254	        { reconfigure: true },
255	      );
256	      this._sheetById.set(sheetId, sheet);
257	      this._objectBySheetId.set(sheetId, object);
258	    });
259	    this._attachSheet(this._authorSheetId);
260	    this._bindControls();
261	    this._renderSheetSelector();
262	    this._renderExportButton();
263	    this._renderStatus("WORKS THEATRE READY");
264	  }
