352	
353	  private _recordFrame(force = false): void {
354	    if (!force && !this._sampling) return;
355	    const object = this._objectBySheetId.get(this._authorSheetId);
356	    const scrub = this._recordScrub;
357	    const engine = this._engine;
358	    if (!object || !scrub || !engine) return;
