584	    private function normalizeAssetOrUrl(string $value): ?string
585	    {
586	        $normalized = trim($value);
587	        if ($normalized === '') {
588	            return null;
589	        }
590	
591	        if ($this->isExternalUrl($normalized)) {
592	            return $normalized;
593	        }
594	
595	        return $this->buildAssetUrl($normalized);
596	    }
