741	    private function formatDate($value): ?string
742	    {
743	        $dateValue = trim((string) $value);
744	        if ($dateValue === '') {
745	            return null;
746	        }
747	
748	        $timestamp = strtotime($dateValue);
749	        if ($timestamp === false) {
750	            return null;
751	        }
752	
753	        return date('Y.m.d', $timestamp);
754	    }
